import base64,json,sys,pathlib,xml.etree.ElementTree as ET,hashlib,html,re
root=pathlib.Path(sys.argv[1]);run=sys.argv[2];sha=sys.argv[3]
caps=root/('region1-canon-captures-'+run)
def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
def esc(s):return html.escape(s)
pairs={}
for scale in ['panoramica','regional']:
 for aspect in ['vertical','horizontal']:
  key=scale+'-'+aspect;a=caps/(scale+'-antes-composicion-'+aspect+'-source.json');b=caps/(key+'-source.json');ma=json.loads(a.read_text());mb=json.loads(b.read_text());assert all(ma[k]==mb[k] for k in ma if k not in ['label','sha256'])
  pairs[key]={'before':data(caps/(scale+'-antes-composicion-'+aspect+'-unity.png')),'after':data(caps/(key+'-unity.png')),'width':mb['width'],'height':mb['height'],'camera':{k:mb[k] for k in ['zoom','aspect','cameraPosition','cameraRotation','worldTarget']},'hashBefore':ma['sha256'],'hashAfter':mb['sha256']}
test=ET.parse(root/'eldoria-region1-canon-tests.xml').getroot().attrib
